H.background();
const w = H.W, h = H.H;
const N = Math.max(1, Math.round(P.N));
const A = Math.max(0.0005, P.area); // floor only to avoid zero; slider range is 0.002-0.05 m^2
const Bm = Math.max(0.05, P.Bmax);
// Magnet oscillates horizontally toward/away from a fixed coil. Position in meters.
const coilX = w * 0.66, coilY = h * 0.55;
const xMag = -0.30 * Math.sin(t * 1.1); // meters, magnet center relative to coil (negative = left of coil)
const vMag = -0.30 * 1.1 * Math.cos(t * 1.1); // d(xMag)/dt, m/s
const gap = (coilX - 70) - Math.abs(xMag) * 280; // pixel distance not used for physics, only drawing
// Flux through coil: model B at the coil as Bmax * (d0^2)/(d0^2 + dist^2), dist = |xMag|.
const d0 = 0.12;
const dist = Math.abs(xMag);
const Bcoil = Bm * (d0 * d0) / (d0 * d0 + dist * dist);
const flux = Bcoil * A; // Wb (per turn)
// dPhi/dt via chain rule: dB/ddist * ddist/dt ; ddist/dt = sign(xMag)*vMag
const dBddist = Bm * (d0 * d0) * (-2 * dist) / Math.pow(d0 * d0 + dist * dist, 2);
const ddistdt = (xMag === 0 ? 0 : Math.sign(xMag) * vMag);
const dPhidt = dBddist * ddistdt * A;
const emf = -N * dPhidt; // volts
// Draw coil as stacked loops (front view ellipses)
const magX = coilX - 150 + xMag * 280; // pixels: magnet drawn left of coil, moves with xMag
const magY = coilY;
// magnet (N red / S blue)
H.rect(magX - 46, magY - 16, 46, 32, { fill: H.colors.warn });
H.rect(magX, magY - 16, 46, 32, { fill: H.colors.accent });
H.text("N", magX - 30, magY + 6, { color: H.colors.ink, size: 16, weight: 700 });
H.text("S", magX + 14, magY + 6, { color: H.colors.ink, size: 16, weight: 700 });
// field arrow from magnet toward coil
H.arrow(magX + 46, magY, magX + 46 + 64, magY, { color: H.colors.violet, width: 3 });
H.text("B", magX + 46 + 70, magY - 6, { color: H.colors.violet, size: 14 });
// coil loops
for (let i = 0; i < 6; i++) {
  H.circle(coilX + i * 6, coilY, 46, { stroke: H.colors.good, width: 3 });
}
H.line(coilX - 2, coilY - 46, coilX + 34, coilY - 46, { color: H.colors.good, width: 3 });
// Induced current direction: sign of emf -> arrow around the loop top
const approaching = (ddistdt < 0); // distance shrinking -> flux rising
H.arrow(coilX + 16, coilY - 52, coilX + 16 + (emf >= 0 ? 30 : -30), coilY - 52, { color: H.colors.accent2, width: 3 });
H.text("I_ind", coilX + 30, coilY - 60, { color: H.colors.accent2, size: 13 });
// Lenz verdict
const verdict = approaching ? "magnet approaching: flux ↑ → induced I opposes (repels)" : "magnet leaving: flux ↓ → induced I sustains (attracts)";
H.text("Lenz's law:  EMF = −N · dΦ/dt", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Φ = " + flux.toFixed(4) + " Wb    dΦ/dt = " + dPhidt.toFixed(4) + " Wb/s    EMF = " + emf.toFixed(3) + " V", 24, 52, { color: H.colors.sub, size: 13 });
H.text(verdict, 24, h - 22, { color: H.colors.good, size: 13 });
H.legend([{ label: "magnet B", color: H.colors.violet }, { label: "coil", color: H.colors.good }, { label: "induced I", color: H.colors.accent2 }], w - 170, 28);
